// Laravel DispatchLectureClipExtractionJob payload.
// action=clip_lecture, lesson_id, video_url/youtube_url/rutube_url, spans[], callback_url.
const body = $input.first().json.body ?? $input.first().json;
if (body.action !== 'clip_lecture') {
  throw new Error('unexpected action: ' + (body.action ?? 'missing'));
}
const spans = Array.isArray(body.spans) ? body.spans : [];
if (!spans.length) {
  throw new Error('no spans — nothing to cut');
}
// Источник: youtube предпочтительнее (на хосте настроен yt-dlp с oauth2),
// rutube — запасной. video_url в этой инсталляции всегда пуст.
const source = body.youtube_url || body.video_url || body.rutube_url || '';
if (!source) {
  throw new Error('lesson has no video url');
}
return spans.map((s, i) => ({
  json: {
    lesson_id: body.lesson_id,
    lesson_title: body.lesson_title ?? '',
    video_url: source,
    callback_url: body.callback_url,
    start_seconds: s.start_seconds,
    end_seconds: s.end_seconds,
    title: s.title || ('clip-' + (i + 1)),
    index: i + 1,
  },
}));

// Готовим shell-команду на хост с yt-dlp/ffmpeg (тот же SSH-кред, что у
// «Скачиваем аудио» в ZOOM-сценарии). Собираем строку здесь, а не в SSH-ноде:
// в JS экранирование кавычек читаемо и проверяемо.
const token = $env.VK_ACCESS_TOKEN;
const groupId = $env.VK_VIDEO_GROUP_ID;
if (!token) {
  throw new Error('n8n env VK_ACCESS_TOKEN не задан — нужен токен с правами video');
}
if (!groupId) {
  throw new Error('n8n env VK_VIDEO_GROUP_ID не задан (id сообщества, куда льём клипы)');
}

// Одинарные кавычки в bash: закрыть, вставить экранированную, открыть заново.
const sh = (v) => "'" + String(v).replace(/'/g, "'\\''") + "'";

return $input.all().map((item) => {
  const j = item.json;
  const src = '/data/clips/src-' + j.lesson_id + '.mp4';
  const out = '/data/clips/lesson-' + j.lesson_id + '-' + j.index + '.mp4';
  const title = String(j.title).slice(0, 120);

  const command = [
    'set -eu',
    'mkdir -p /data/clips',
    // Исходник тянем один раз на всю лекцию: спанов до 5, качать их по отдельности
    // значило бы 5 полных загрузок полуторачасового видео.
    '[ -s ' + sh(src) + ' ] || yt-dlp --extractor-args "youtube:oauth2" --extractor-args "youtube:player_client=android,web" -f "bv*+ba/b" --merge-output-format mp4 --no-warnings -o ' + sh(src) + ' ' + sh(j.video_url),
    // -c copy: без перекодирования, режем по ключевым кадрам — секунды, не минуты.
    'ffmpeg -y -hide_banner -loglevel error -ss ' + Number(j.start_seconds) + ' -to ' + Number(j.end_seconds) + ' -i ' + sh(src) + ' -c copy ' + sh(out),
    // video.save отдаёт upload_url и уже готовые owner_id/video_id.
    'SAVE=$(curl -s -G "https://api.vk.com/method/video.save" --data-urlencode ' + sh('name=' + title) + ' --data-urlencode ' + sh('group_id=' + groupId) + ' --data-urlencode ' + sh('access_token=' + token) + ' --data-urlencode "v=5.131")',
    'printf %s "$SAVE" | grep -q upload_url || { printf %s "$SAVE" >&2; exit 1; }',
    'UP=$(printf %s "$SAVE" | python3 -c "import sys,json;print(json.load(sys.stdin)[\'response\'][\'upload_url\'])")',
    'curl -s -F ' + sh('video_file=@' + out) + ' "$UP" > /dev/null',
    'rm -f ' + sh(out),
    'printf %s "$SAVE" | python3 -c "import sys,json;r=json.load(sys.stdin)[\'response\'];print(json.dumps({\'vk_video_id\':r[\'video_id\'],\'vk_owner_id\':r[\'owner_id\']}))"',
  ].join('\n');

  return { json: { ...j, command } };
});

// SSH-нода кладёт вывод в stdout. Последняя строка — JSON с id ролика.
return $input.all().map((item) => {
  const raw = String(item.json.stdout ?? '').trim();
  const last = raw.split('\n').filter(Boolean).pop() ?? '';
  let parsed = {};
  try {
    parsed = JSON.parse(last);
  } catch (e) {
    throw new Error('не разобрать ответ VK: ' + raw.slice(0, 200));
  }
  return { json: parsed };
});

// Собираем один callback на всю лекцию. Поля спана берём из «Expand spans»
// по индексу: цепочка линейная и 1:1, порядок сохраняется, а $json к этому
// моменту содержит только ответ VK.
const vkItems = $input.all();
const spans = $('Expand spans').all();
const clips = vkItems.map((it, i) => {
  const s = spans[i] ? spans[i].json : {};
  const v = it.json;
  return {
    start_seconds: s.start_seconds,
    end_seconds: s.end_seconds,
    title: s.title,
    vk_video_id: String(v.vk_video_id ?? ''),
    vk_owner_id: String(v.vk_owner_id ?? ''),
  };
});
const first = spans[0] ? spans[0].json : {};
return [{
  json: {
    callback_url: first.callback_url,
    lesson_id: first.lesson_id,
    body: {
      lesson_id: first.lesson_id,
      clips,
    },
  },
}];
